// Freeze the external cache client so every allocation executes the same verified release.
const release='v0.18.0';const expectedArchive='45f1447fbe231e3037bde351ef70677dd212216c8d62ae7ca409fecc4d6acc89';const expectedExecutable='973cb15f6a986d84ca334bbed3bbe2eb8f1ee8fd81bf9e115b8539a293bf8d59';
const {readFileSync,writeFileSync,mkdirSync,chmodSync,existsSync,appendFileSync,readdirSync,statSync}=await import('node:fs');const {homedir,hostname,availableParallelism,totalmem}=await import('node:os');const {join,relative}=await import('node:path');const {execFileSync,spawnSync}=await import('node:child_process');const {createHash}=await import('node:crypto');const {strict:assert}=await import('node:assert');const sha=b=>createHash('sha256').update(b).digest('hex');const root=process.env.GITHUB_WORKSPACE;assert(root);const scratch=join(homedir(),'temp/agent');mkdirSync(scratch,{recursive:true,mode:0o700});chmodSync(scratch,0o700);const evidence=join(scratch,'depot-sccache-evidence');mkdirSync(evidence,{recursive:true,mode:0o700});appendFileSync(process.env.GITHUB_OUTPUT,'evidence-path='+evidence+'\n');const role=process.env.PROBE_ROLE;assert(['seed','warm','changed-flags'].includes(role));const target=join(scratch,'depot-sccache-cargo-target');const cargoHome=join(scratch,'depot-sccache-cargo-home');const cacheDir=join(scratch,'depot-sccache-private-disk-cache');const freshTarget=!existsSync(target);const freshCargoHome=!existsSync(cargoHome);const client=join(scratch,'sccache');const crate=join(root,'package/music-player/truepeak-core');const manifest=join(crate,'Cargo.toml');const lock=join(crate,'Cargo.lock');const files=execFileSync('git',['ls-files','package/music-player/truepeak-core','.depot/probe/sccache','.depot/workflows/depot-sccache-probe.yml'],{cwd:root,encoding:'utf8'}).trim().split('\n');const sourceHashes=Object.fromEntries(files.map(path=>[path,sha(readFileSync(join(root,path)))]));const proof={schemaVersion:1,provider:'depot-ci',startedAt:new Date().toISOString(),role,sourceHead:execFileSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8'}).trim(),sourceHashes,runner:{hostname:hostname(),bootId:readFileSync('/proc/sys/kernel/random/boot_id','utf8').trim(),cpus:availableParallelism(),memoryBytes:totalmem(),node:process.version},paths:{root,crate,target,cargoHome,cacheDir},freshTarget,freshCargoHome,cache:{credentialSource:'DEPOT_CACHE_TOKEN',credentialPresent:Boolean(process.env.DEPOT_CACHE_TOKEN),endpoint:'https://cache.depot.dev',keyPrefix:process.env.PROBE_CACHE_PREFIX,backend:'WebDAV',archiveRestore:false},client:{release,archiveSha256:expectedArchive,executableSha256:expectedExecutable},commands:[],tests:{available:null,executed:false},failure:null};let env;let serverStarted=false;let failure;function record({name,args,cwd=root,allowFailure=false}){const begin=new Date().toISOString();const out=spawnSync(name,args,{cwd,env,encoding:'utf8',timeout:180000,maxBuffer:8*1024*1024});const item={name,args,cwd,startedAt:begin,finishedAt:new Date().toISOString(),exitStatus:out.status,signal:out.signal,errorCode:out.error?.code??null,stdout:out.stdout??'',stderr:out.stderr??''};proof.commands.push(item);writeFileSync(join(evidence,'proof.json'),JSON.stringify(proof,null,2)+'\n');if(!allowFailure)assert.equal(out.status,0,name+' '+args.join(' ')+' failed: '+item.stderr);return item}try{assert(freshTarget&&freshCargoHome,'Expected fresh isolated Cargo paths');assert(proof.cache.credentialPresent,'No automatic Cache credential');assert(proof.cache.keyPrefix,'Missing isolated cache namespace');const archive='sccache-'+release+'-x86_64-unknown-linux-musl.tar.gz';const url='https://github.com/mozilla/sccache/releases/download/'+release+'/'+archive;const response=await fetch(url,{signal:AbortSignal.timeout(45000)});assert(response.ok);const bytes=Buffer.from(await response.arrayBuffer());assert.equal(sha(bytes),expectedArchive);const archivePath=join(scratch,archive);writeFileSync(archivePath,bytes);const entries=execFileSync('tar',['--list','--gzip','--file',archivePath],{encoding:'utf8'}).trim().split('\n');assert(entries.every(path=>!path.startsWith('/')&&!path.split('/').includes('..')));const member=entries.find(path=>path.endsWith('/sccache'));assert(member);const binary=execFileSync('tar',['--extract','--gzip','--file',archivePath,'--to-stdout',member],{maxBuffer:64*1024*1024});assert.equal(sha(binary),expectedExecutable);writeFileSync(client,binary,{mode:0o700});chmodSync(client,0o700);const base=Object.fromEntries(Object.entries(process.env).filter(([key])=>!key.startsWith('SCCACHE_')&&key!=='DEPOT_TOKEN'));const flags='--cfg=depot_sccache_probe_base'+(role==='changed-flags'?' --cfg=depot_sccache_probe_changed':'');env={...base,RUSTUP_TOOLCHAIN:'stable',CARGO_HOME:cargoHome,CARGO_TARGET_DIR:target,CARGO_INCREMENTAL:'0',CARGO_BUILD_JOBS:'2',RUSTFLAGS:flags,RUSTC_WRAPPER:client,SCCACHE_DIR:cacheDir,SCCACHE_SERVER_PORT:'42771',SCCACHE_WEBDAV_ENDPOINT:'https://cache.depot.dev',SCCACHE_WEBDAV_USERNAME:'l4zncjjbj5',SCCACHE_WEBDAV_PASSWORD:process.env.DEPOT_CACHE_TOKEN,SCCACHE_WEBDAV_KEY_PREFIX:proof.cache.keyPrefix};proof.rustflags=flags;proof.client.version=record({name:client,args:['--version']}).stdout.trim();const rust=record({name:'rustc',args:['--version','--verbose']});proof.toolchain={rustcVerbose:rust.stdout,cargoVersion:record({name:'cargo',args:['--version']}).stdout.trim(),sysroot:record({name:'rustc',args:['--print','sysroot']}).stdout.trim()};assert(rust.stdout.startsWith('rustc 1.97.1 '),'Frozen preinstalled compiler version changed');proof.toolchain.rustcSha256=sha(readFileSync(join(proof.toolchain.sysroot,'bin/rustc')));record({name:client,args:['--start-server']});serverStarted=true;record({name:client,args:['--zero-stats']});record({name:'cargo',args:['build','--manifest-path',manifest,'--release','--no-default-features','--locked','--jobs','2']});proof.afterLibraryBuild=JSON.parse(record({name:client,args:['--show-stats','--stats-format','json']}).stdout);const rustHits=proof.afterLibraryBuild.stats.cache_hits.counts.Rust??0;const rustMisses=proof.afterLibraryBuild.stats.cache_misses.counts.Rust??0;proof.cache.result={rustHits,rustMisses,writes:proof.afterLibraryBuild.stats.cache_writes,writeErrors:proof.afterLibraryBuild.stats.cache_write_errors,readErrors:proof.afterLibraryBuild.stats.cache_read_errors};assert.equal(proof.cache.result.writeErrors,0,'Compiler-cache writes failed');assert.equal(proof.cache.result.readErrors,0,'Compiler-cache reads failed');if(role==='warm'){assert(rustHits>0,'Fresh warm allocation had no Rust compiler-cache hits');assert.equal(rustMisses,0,'Unchanged fresh allocation recompiled a cacheable Rust input')}else{assert(rustMisses>0,'Cold/changed compiler input did not produce a measured miss');assert(proof.cache.result.writes>0,'No successful cache writes despite compiler misses')}const rlib=join(target,'release/libtruepeak_core.rlib');assert(existsSync(rlib));const consumer=join(scratch,'truepeak-cache-consumer');record({name:'rustc',args:['--edition=2024',join(root,'.depot/probe/sccache/consumer.rs'),'--extern','truepeak_core='+rlib,'-L','dependency='+join(target,'release/deps'),'-o',consumer]});record({name:consumer,args:[]});proof.consumer={executed:true,exitStatus:0,rlibSha256:sha(readFileSync(rlib)),executableSha256:sha(readFileSync(consumer)),cases:['Quiet signal stays at unity gain','One-sample meter reports exact amplitude']};const nextest=record({name:'cargo',args:['nextest','--version'],allowFailure:true});proof.tests.available=nextest.exitStatus===0;proof.tests.version=nextest.exitStatus===0?nextest.stdout.trim():null;if(proof.tests.available){proof.tests.executed=true;record({name:'cargo',args:['nextest','run','--manifest-path',manifest,'--release','--no-default-features','--locked']});}else{proof.tests.reason='cargo nextest unavailable in this base sandbox; no cargo-test fallback used'}proof.afterAll=JSON.parse(record({name:client,args:['--show-stats','--stats-format','json']}).stdout);assert.equal(sha(readFileSync(lock)),sourceHashes['package/music-player/truepeak-core/Cargo.lock'],'Lockfile changed');}catch(error){failure=error;proof.failure={name:error instanceof Error?error.name:'UnknownThrownValue',message:error instanceof Error?error.message:String(error)};}finally{if(serverStarted){const stop=record({name:client,args:['--stop-server'],allowFailure:true});proof.serverShutdown={exitStatus:stop.exitStatus,signal:stop.signal};if(stop.exitStatus!==0&&!failure){failure=new Error('sccache server shutdown failed');proof.failure={name:failure.name,message:failure.message}}}proof.finishedAt=new Date().toISOString();writeFileSync(join(evidence,'proof.json'),JSON.stringify(proof,null,2)+'\n');console.log('SCCACHE_PROOF '+JSON.stringify({role:proof.role,sourceHead:proof.sourceHead,runner:proof.runner,cache:proof.cache,tests:proof.tests,failure:proof.failure,serverShutdown:proof.serverShutdown}));}if(failure)throw failure;
